from typing import Annotated
from fastapi import FastAPI, Cookie

app = FastAPI()

@app.get("/read-cookie/")
def read_cookie(session_id: Annotated[str | None, Cookie()] = None):
    return {"session_id": session_id}

from fastapi import Header

@app.get("/read-header/")
def read_header(
    user_agent: Annotated[str | None, Header()] = None,
    x_custom: Annotated[str | None, Header(alias="X-Custom")] = None,
):
    return {"user_agent": user_agent, "x_custom": x_custom}

from fastapi import Form

@app.post("/login/")
def login(username: Annotated[str, Form()], password: Annotated[str, Form()]):
    return {"username": username}

from fastapi import Response

@app.post("/set-cookie/")
def set_cookie(response: Response):
    response.set_cookie(key="session", value="abc123", httponly=True, secure=True, samesite="lax")
    return {"message": "Cookie set"}
